// Board Support Package interface for the RP2040 port-validation example.
// Handwritten for qp-arduino (QP/C++ v7.3.4). Not generated by QM.
#ifndef BSP_HPP
#define BSP_HPP

class BSP {
public:
    enum { TICKS_PER_SEC = 100 };

    // role of the second analyzer probe (GP25 on the fixture), QS command 5
    enum Role : std::uint8_t {
        ROLE_MARKER = 0U,   // marker pulses: entry of `running`, QS command 3
        ROLE_DISPATCH = 1U, // high while the Validator dispatches an event (default)
        ROLE_IDLE = 2U,     // high while the QV idle callback runs
        ROLE_EVENT = 3U     // pulse on receipt of each dynamic event
    };

    static void init();
    static void setRole(std::uint8_t role);
    static void roleHigh(std::uint8_t role);
    static void roleLow(std::uint8_t role);
    static void rolePulse(std::uint8_t role);
};

#endif // BSP_HPP
